  for (let i = 0; i < 10; i++) applyRequirementUpdates(ledger, [{ id: "R1", evidence: [`item ${i}`] }]);
  assert.deepEqual(Object.keys(req.evidenceSources ?? {}).sort(), [...req.evidence].sort());
});
