    assert.ok(await eventually(() => s.received("shutdown").length === 1 && s.received("exit").length === 1 && s.log().some((e) => e.event === "signal" && e.signal === "SIGTERM")), JSON.stringify(s.log().map((e) => e.method ?? e.event)));
